SELECT COUNT(*) FROM votes as v, posts as p, postHistory as ph, users as u WHERE p.OwnerUserId = u.Id AND v.UserId = u.Id AND ph.UserId = u.Id AND v.BountyAmount>=0 AND v.CreationDate>='2010-05-19 00:00:00'::timestamp AND p.AnswerCount>=0 AND p.AnswerCount<=9 AND p.CreationDate>='2010-07-20 18:17:25'::timestamp AND p.CreationDate<='2014-08-26 12:57:22'::timestamp AND ph.CreationDate<='2014-09-02 07:58:47'::timestamp;